export interface ConvaiService {
  Hello(request: HelloRequest): Promise<HelloResponse>;
  HelloStream(request: Observable<HelloRequest>): Observable<HelloResponse>;
  SpeechToText(request: Observable<STTRequest>): Observable<STTResponse>;
  GetResponse(request: Observable<GetResponseRequest>): Observable<GetResponseResponse>;
  GetResponseSingle(request: GetResponseRequestSingle): Observable<GetResponseResponse>;
  SubmitFeedback(request: FeedbackRequest): Promise<FeedbackResponse>;
}

export const ConvaiServiceServiceName = "service.ConvaiService";
export class ConvaiServiceClientImpl implements ConvaiService {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || ConvaiServiceServiceName;
    this.rpc = rpc;
    this.Hello = this.Hello.bind(this);
    this.HelloStream = this.HelloStream.bind(this);
    this.SpeechToText = this.SpeechToText.bind(this);
    this.GetResponse = this.GetResponse.bind(this);
    this.GetResponseSingle = this.GetResponseSingle.bind(this);
    this.SubmitFeedback = this.SubmitFeedback.bind(this);
  }
  Hello(request: HelloRequest): Promise<HelloResponse> {
    const data = HelloRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "Hello", data);
    return promise.then((data) => HelloResponse.decode(new BinaryReader(data)));
  }

  HelloStream(request: Observable<HelloRequest>): Observable<HelloResponse> {
    const data = request.pipe(map((request) => HelloRequest.encode(request).finish()));
    const result = this.rpc.bidirectionalStreamingRequest(this.service, "HelloStream", data);
    return result.pipe(map((data) => HelloResponse.decode(new BinaryReader(data))));
  }

  SpeechToText(request: Observable<STTRequest>): Observable<STTResponse> {
    const data = request.pipe(map((request) => STTRequest.encode(request).finish()));
    const result = this.rpc.bidirectionalStreamingRequest(this.service, "SpeechToText", data);
    return result.pipe(map((data) => STTResponse.decode(new BinaryReader(data))));
  }

  GetResponse(request: Observable<GetResponseRequest>): Observable<GetResponseResponse> {
    const data = request.pipe(map((request) => GetResponseRequest.encode(request).finish()));
    const result = this.rpc.bidirectionalStreamingRequest(this.service, "GetResponse", data);
    return result.pipe(map((data) => GetResponseResponse.decode(new BinaryReader(data))));
  }

  GetResponseSingle(request: GetResponseRequestSingle): Observable<GetResponseResponse> {
    const data = GetResponseRequestSingle.encode(request).finish();
    const result = this.rpc.serverStreamingRequest(this.service, "GetResponseSingle", data);
    return result.pipe(map((data) => GetResponseResponse.decode(new BinaryReader(data))));
  }

  SubmitFeedback(request: FeedbackRequest): Promise<FeedbackResponse> {
    const data = FeedbackRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "SubmitFeedback", data);
    return promise.then((data) => FeedbackResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
  clientStreamingRequest(service: string, method: string, data: Observable<Uint8Array>): Promise<Uint8Array>;
  serverStreamingRequest(service: string, method: string, data: Uint8Array): Observable<Uint8Array>;
  bidirectionalStreamingRequest(service: string, method: string, data: Observable<Uint8Array>): Observable<Uint8Array>;
}

